--
-- Name: convert_gamets2skyrim_date_fmt(bigint, text); Type: FUNCTION; Schema: public; Owner: dwemer
--

CREATE FUNCTION public.convert_gamets2skyrim_date_fmt(gamets bigint, s_format text) RETURNS text
    LANGUAGE plpgsql
    AS $$
        DECLARE 
            s_date text; 
            s_format text; 
            f_hours float;
            ts_base timestamp;
            ts2 timestamp;
        BEGIN
            IF (s_format IS NULL) OR (LENGTH(s_format) < 1) THEN
                s_format := 'YYYY.MM.DD HH24:MI'; 
            END IF;
            f_hours := (gamets * 0.0000024);
            ts_base := to_timestamp('0201.08.17 00:00:00','YYYY.MM.DD HH24:MI:SS');
            ts2 := ts_base  + f_hours * INTERVAL '1 hour';
            RETURN to_char(ts2, s_format);
        END;
    $$;


