INSERT INTO public.oghma VALUES ('potion_of_plentiful_magicka', 'A potent potion that restores a significant amount of magicka, ensuring spellcasters can continue their craft. Restores a significant amount of magicka, allowing spellcasters to maintain their magical prowess during extended encounters. These potions can be found in random loot or purchased from alchemists.', '''alchemist'':48B ''allow'':27B ''amount'':12B,24B ''continu'':18B ''craft'':20B ''encount'':36B ''ensur'':15B ''extend'':35B ''found'':41B ''loot'':44B ''magic'':32B ''magicka'':4A,14B,26B ''maintain'':30B ''plenti'':3A ''potent'':6B ''potion'':1A,7B,38B ''prowess'':33B ''purchas'':46B ''random'':43B ''restor'':9B,21B ''signific'':11B,23B ''spellcast'':16B,28B', 'mage, alchemist, scholar, collegeofwinterhold, psijic', 'The Potion of Plentiful Magicka restores a significant amount of magicka for longer magical battles. You do not know the full effects or details of this potion. However, an alchemist might.', '', '', 'items');
