INSERT INTO public.oghma VALUES ('autumnwatch_tower', 'Autumnwatch Tower is a dragon lair located south of Ivarstead and west of Froki''s Shack in the Rift. The site consists of two abandoned towers connected by a stone bridge.', '''abandon'':27B ''autumnwatch'':1A,3B ''bridg'':33B ''connect'':29B ''consist'':24B ''dragon'':7B ''froki'':16B ''ivarstead'':12B ''lair'':8B ''locat'':9B ''rift'':21B ''shack'':18B ''site'':23B ''south'':10B ''stone'':32B ''tower'':2A,4B,28B ''two'':26B ''west'':14B', 'rift, dragon', 'Autumnwatch Tower is a dragon lair located south of Ivarstead.You do not know anything else about this area.', 'skyrimall, eastmarch, falkreath', '', 'rift');
INSERT INTO public.oghma VALUES ('beggar''s_row', 'Beggar''s Row is a small section of Riften''s sewer system that has been repurposed as a refuge for the homeless. Located in lower Riften by the canal, it lies opposite Elgrim''s Elixirs and near the northern stairs leading down from upper Riften. ', '''beggar'':1A,4B ''canal'':32B ''elgrim'':36B ''elixir'':38B ''homeless'':25B ''lead'':44B ''lie'':34B ''locat'':26B ''lower'':28B ''near'':40B ''northern'':42B ''opposit'':35B ''refug'':22B ''repurpos'':19B ''riften'':12B,29B,48B ''row'':3A,6B ''section'':10B ''sewer'':14B ''small'':9B ''stair'':43B ''system'':15B ''upper'':47B', 'rift', 'Beggar''s Row is a small section of Riften''s sewer system that has been repurposed as a refuge for the homeless.You do not know anything else about this area.', 'skyrimall, eastmarch, falkreath', '', 'rift');
