INSERT INTO public.oghma VALUES ('white_ridge_barrow', 'White Ridge Barrow is a medium-sized Nordic ruin situated in the northern reaches of Solstheim, nestled between the rugged peaks and snow-laden forests of the island. It lies west of Hrothmund''s Barrow and east of the Stalhrim Source, making it a notable landmark for travelers navigating this remote region. Though its weathered exterior speaks of an ancient past, the barrow has become a refuge for bandits who now claim its halls as their stronghold.', '''ancient'':65B ''bandit'':74B ''barrow'':3A,6B,40B,68B ''becom'':70B ''claim'':77B ''east'':42B ''exterior'':61B ''forest'':30B ''hall'':79B ''hrothmund'':38B ''island'':33B ''laden'':29B ''landmark'':51B ''lie'':35B ''make'':47B ''medium'':10B ''medium-s'':9B ''navig'':54B ''nestl'':21B ''nordic'':12B ''northern'':17B ''notabl'':50B ''past'':66B ''peak'':25B ''reach'':18B ''refug'':72B ''region'':57B ''remot'':56B ''ridg'':2A,5B ''rug'':24B ''ruin'':13B ''situat'':14B ''size'':11B ''snow'':28B ''snow-laden'':27B ''solstheim'':20B ''sourc'':46B ''speak'':62B ''stalhrim'':45B ''stronghold'':82B ''though'':58B ''travel'':53B ''weather'':60B ''west'':36B ''white'':1A,4B', 'solstheim', 'You do not know anything about this area.', '', '', 'solstheim');
