INSERT INTO public.oghma VALUES ('ragnvald', 'Ragnvald is a medium-sized Nordic ruin located north of Markarth and south-southwest of Bthardamz in the Reach. The ruin is inhabited by draugr and houses the dragon priest Otar the Mad, who lays to rest here.', '''bthardamz'':19B ''dragon'':32B ''draugr'':28B ''hous'':30B ''inhabit'':26B ''lay'':38B ''locat'':10B ''mad'':36B ''markarth'':13B ''medium'':6B ''medium-s'':5B ''nordic'':8B ''north'':11B ''otar'':34B ''priest'':33B ''ragnvald'':1A,2B ''reach'':22B ''rest'':40B ''ruin'':9B,24B ''size'':7B ''south'':16B ''south-southwest'':15B ''southwest'':17B', 'reach', 'Ragnvald is a medium-sized Nordic ruin located north of Markarth in the Reach. You do not know anything else about this area.', 'skyrimall, falkreath, whiterun, hjaalmarch, haafingar', '', 'reach');
