INSERT INTO public.oghma VALUES ('mystic_venom', 'Mystic Venom is a poison of mysterious origin, said to sap both the health and magical reserves of its victims. It can be harvested from the Elytra Nymphs of the Shivering Isles, creatures tied to a chaotic and otherworldly realm.', '''chaotic'':39B ''creatur'':35B ''elytra'':29B ''harvest'':26B ''health'':16B ''isl'':34B ''magic'':18B ''mysteri'':9B ''mystic'':1A,3B ''nymph'':30B ''origin'':10B ''otherworld'':41B ''poison'':7B ''realm'':42B ''reserv'':19B ''said'':11B ''sap'':13B ''shiver'':33B ''tie'':36B ''venom'':2A,4B ''victim'':22B', 'daedric, alchemist, scholar', 'You know little of this venom beyond its association with the mystical creatures of the Shivering Isles.', '', '', 'items');
