INSERT INTO public.oghma VALUES ('shock_damage', 'These magical effects are offensive Destruction abilities that deal immediate lightning damage and drain magicka from the target. This effect is available as a spell, can be applied through custom enchanting, and is also found on enchanted gear, making it a staple for countering mages.', '''abil'':9B ''also'':36B ''appli'':30B ''avail'':24B ''counter'':46B ''custom'':32B ''damag'':2A,14B ''deal'':11B ''destruct'':8B ''drain'':16B ''effect'':5B,22B ''enchant'':33B,39B ''found'':37B ''gear'':40B ''immedi'':12B ''lightn'':13B ''mage'':47B ''magic'':4B ''magicka'':17B ''make'':41B ''offens'':7B ''shock'':1A ''spell'':27B ''stapl'':44B ''target'':20B', 'mage', 'This spell shocks enemies with lightning, hurting them and draining their magicka. A mage might know more though.', '', '', 'spells');
