INSERT INTO public.oghma VALUES ('imp_stool', 'Imp Stool is a  brown capped fungus found in caves, typically growing near the edges where the wall and floor meet. Alchemy effects: Damage Health, Lingering Damage Health, Paralysis, and Restore Health.', '''alchemi'':24B ''brown'':7B ''cap'':8B ''cave'':12B ''damag'':26B,29B ''edg'':17B ''effect'':25B ''floor'':22B ''found'':10B ''fungus'':9B ''grow'':14B ''health'':27B,30B,34B ''imp'':1A,3B ''linger'':28B ''meet'':23B ''near'':15B ''paralysi'':31B ''restor'':33B ''stool'':2A,4B ''typic'':13B ''wall'':20B', 'alchemist', 'Imp Stool is a  brown capped fungus found in caves, typically growing near the edges where the wall and floor meet. 
