INSERT INTO public.oghma VALUES ('hob''s_fall_cave', 'Hob''s Fall Cave is a small cave located along the coast between Winterhold and Dawnstar, in the Winterhold region. The cave is relatively isolated, nestled within the rugged coastal landscape. It is rumored that warlocks have taken over the cave.', '''along'':14B ''cave'':4A,8B,12B,26B,45B ''coast'':16B ''coastal'':34B ''dawnstar'':20B ''fall'':3A,7B ''hob'':1A,5B ''isol'':29B ''landscap'':35B ''locat'':13B ''nestl'':30B ''region'':24B ''relat'':28B ''rug'':33B ''rumor'':38B ''small'':11B ''taken'':42B ''warlock'':40B ''winterhold'':18B,23B ''within'':31B', 'winterhold', 'Hob''s Fall Cave is a small cave located along the coast between Winterhold and Dawnstar, in the Winterhold region.You do not know anything else about this area.', 'skyrimall, pale, eastmarch', '', 'winterhold');
